<?php
/**
 * Ministrant Manager - atomic legacy web security hardening.
 * Run from /home/<user>/ next to public_html/:
 *   php apply_legacy_web_hardening.php
 */
declare(strict_types=1);

$publicRoot = __DIR__ . '/public_html';
if (!is_dir($publicRoot)) {
    fwrite(STDERR, "ERROR: expected public_html/ next to this script.\n");
    exit(1);
}

$plan = json_decode("{\"config/database.php\":{\"baseline\":\"040fc7b0048ddf3b902de0c7cf12b7f2b320a350f9ef34cfa8b2769df4cf5d3e\",\"patched\":\"0c4914730aa74a94409b01d1f357d8a7b9a56e17d70a62a7f43016c88e47b63f\",\"content\":\"\"},\"public/empty.php\":{\"baseline\":\"3d6e333e29247a0e96a67e82c4ead1436b6a7229ced121868d2a16839d693ce0\",\"patched\":\"55aac8e4531d5df8a6ff853fba1bdb32a01ed18bc1e1dff148a51a079d316487\",\"content\":\"\"},\"public/form.php\":{\"baseline\":\"4b92f2d1dd04cded76b7ff26c54fddc1df3506457f2f23a247caa71fc9d5cd3e\",\"patched\":\"b8dfb5a6a0f11d42e5fe1f6a07cc5ae6a29bb00a1fa0b9566e2eb2afbbb31696\",\"content\":\"\"}}", true, 512, JSON_THROW_ON_ERROR);

function mm_fail(string $message): never {
    fwrite(STDERR, "ERROR: $message\n");
    exit(1);
}
function mm_sha(string $path): string {
    $hash = @hash_file('sha256', $path);
    if (!is_string($hash)) throw new RuntimeException("Cannot hash $path");
    return $hash;
}

$toApply = [];
foreach ($plan as $relative => $entry) {
    $path = $publicRoot . '/' . $relative;
    if (!is_file($path)) mm_fail("missing required legacy file: $relative");
    $current = mm_sha($path);
    if (hash_equals($entry['patched'], $current)) continue;
    if (!hash_equals($entry['baseline'], $current)) {
        mm_fail('unknown SHA-256 for ' . $relative . ': ' . $current
            . ' (expected audited baseline ' . $entry['baseline']
            . ' or patched ' . $entry['patched'] . ')');
    }
    $toApply[$relative] = $entry;
}

if ($toApply === []) {
    echo "LEGACY WEB HARDENING: already applied\n";
    exit(0);
}

$backupRoot = __DIR__ . '/backup_legacy_web_hardening_' . date('Ymd_His');
if (!mkdir($backupRoot, 0700, true) && !is_dir($backupRoot)) {
    mm_fail("cannot create backup directory: $backupRoot");
}

$changed = [];
try {
    foreach ($toApply as $relative => $entry) {
        $source = $publicRoot . '/' . $relative;
        $backup = $backupRoot . '/' . $relative;
        $backupDir = dirname($backup);
        if (!is_dir($backupDir) && !mkdir($backupDir, 0700, true) && !is_dir($backupDir)) {
            throw new RuntimeException("cannot create backup directory for $relative");
        }
        if (!copy($source, $backup)) throw new RuntimeException("cannot back up $relative");

        $decoded = base64_decode($entry['content'], true);
        if ($decoded === false) throw new RuntimeException("invalid embedded patch for $relative");

        $tmp = dirname($source) . '/.' . basename($source) . '.mm-hardening-' . bin2hex(random_bytes(8));
        if (file_put_contents($tmp, $decoded, LOCK_EX) === false) {
            @unlink($tmp);
            throw new RuntimeException("cannot write temporary file for $relative");
        }
        $mode = fileperms($source);
        if (is_int($mode)) @chmod($tmp, $mode & 0777);
        if (!rename($tmp, $source)) {
            @unlink($tmp);
            throw new RuntimeException("cannot atomically replace $relative");
        }
        $changed[] = $relative;

        $actual = mm_sha($source);
        if (!hash_equals($entry['patched'], $actual)) {
            throw new RuntimeException("post-write SHA mismatch for $relative: $actual");
        }
    }
} catch (Throwable $e) {
    $rollbackErrors = [];
    foreach (array_reverse($changed) as $relative) {
        $source = $backupRoot . '/' . $relative;
        $dest = $publicRoot . '/' . $relative;
        if (!is_file($source) || !copy($source, $dest)) $rollbackErrors[] = $relative;
    }
    fwrite(STDERR, "ERROR: " . $e->getMessage() . "\n");
    if ($rollbackErrors !== []) {
        fwrite(STDERR, "ROLLBACK ERROR: " . implode(', ', $rollbackErrors) . "\n");
    } else {
        fwrite(STDERR, "Rollback completed from $backupRoot\n");
    }
    exit(1);
}

echo "LEGACY WEB HARDENING OK\n";
echo "Backup: $backupRoot\n";
foreach (array_keys($toApply) as $relative) echo "  patched: $relative\n";